INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a210-000000000001','quote','Ngày 20-2-1926 — thuận hòa','THẦY vui muốn cho các con thuận hòa cùng nhau hoài, ấy là lễ hiến cho THẦY rất trân trọng.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-20-2-1926','Thánh Ngôn Hiệp Tuyển, quyển 1 — bản điện tử ghi ấn bản 1928; Hội Thánh Tòa Thánh Tây Ninh; bài ngày 20-2-1926','1926-02-20','Đối chiếu bản in và quyền sử dụng trước khi duyệt.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-20-2-1926');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a210-000000000002','quote','Ngày 25-2-1926 — ý nghĩa lạy','- Là tỏ ra bề ngoài, lễ kỉnh trong lòng.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-25-2-1926','Thánh Ngôn Hiệp Tuyển, quyển 1 — bản điện tử ghi ấn bản 1928; Hội Thánh Tòa Thánh Tây Ninh; bài ngày 25-2-1926','1926-02-25','Câu trả lời cho câu hỏi ‘Lạy là gì?’; đối chiếu bản in trước khi duyệt.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-25-2-1926');
INSERT OR IGNORE INTO gdd_research_items(id,kind,title,excerpt,speaker,source_url,citation,source_date,note,discovered_key) VALUES ('f17f8dc1-e43b-4dd3-a210-000000000003','quote','Ngày 13-3-1926 — giữ gìn đạo đức','Ấy vậy rán gìn giữ bộ thiết giáp ấy hoài cho tới ngày các con hội hiệp cùng THẦY.','Đức Chí Tôn','https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-13-3-1926','Thánh Ngôn Hiệp Tuyển, quyển 1 — bản điện tử ghi ấn bản 1928; Hội Thánh Tòa Thánh Tây Ninh; bài ngày 13-3-1926','1926-03-13','‘Bộ thiết giáp’ chỉ đạo đức của môn đệ theo đoạn ngay trước; đọc ngữ cảnh trước khi duyệt.','excerpt:https://thanhgiaocaodai.com/doc/thanh-ngon-hiep-tuyen/ngay-13-3-1926');
